  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"boolean Account.equals(Object)", "int Account.hashCode()"})
  public void testAccountEqualsAndHashCode_whenOtherIsEqual_thenReturnEqual() {
    // Arrange
    Account defaultInstance = Account.getDefaultInstance();
    Account defaultInstance2 = Account.getDefaultInstance();

    // Act and Assert
    assertEquals(defaultInstance, defaultInstance2);
    int expectedHashCodeResult = defaultInstance.hashCode();
    assertEquals(expectedHashCodeResult, defaultInstance2.hashCode());
  }

