  /**
   * Test Account {@link Account#getAccountResource()}.
   * <p>
   * Method under test: {@link Account#getAccountResource()}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Account.AccountResource Account.getAccountResource()"})
  public void testAccountGetAccountResource() {
    // Arrange and Act
    AccountResource actualAccountResource = Account.getDefaultInstance().getAccountResource();

    // Assert
    assertEquals("", actualAccountResource.getInitializationErrorString());
    assertEquals(0, actualAccountResource.getSerializedSize());
    assertEquals(0L, actualAccountResource.getAcquiredDelegatedFrozenBalanceForEnergy());
    assertEquals(0L, actualAccountResource.getAcquiredDelegatedFrozenV2BalanceForEnergy());
    assertEquals(0L, actualAccountResource.getDelegatedFrozenBalanceForEnergy());
    assertEquals(0L, actualAccountResource.getDelegatedFrozenV2BalanceForEnergy());
    assertEquals(0L, actualAccountResource.getEnergyUsage());
    assertEquals(0L, actualAccountResource.getEnergyWindowSize());
    assertEquals(0L, actualAccountResource.getLatestConsumeTimeForEnergy());
    assertEquals(0L, actualAccountResource.getLatestExchangeStorageTime());
    assertEquals(0L, actualAccountResource.getStorageLimit());
    assertEquals(0L, actualAccountResource.getStorageUsage());
    assertFalse(actualAccountResource.getEnergyWindowOptimized());
    assertFalse(actualAccountResource.hasFrozenBalanceForEnergy());
    assertTrue(actualAccountResource.findInitializationErrors().isEmpty());
    assertTrue(actualAccountResource.getAllFields().isEmpty());
    assertTrue(actualAccountResource.isInitialized());
    assertSame(actualAccountResource, actualAccountResource.getDefaultInstanceForType());
  }

