  /**
   * Test Account {@link Account#getDescriptor()}.
   * <p>
   * Method under test: {@link Account#getDescriptor()}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Descriptors.Descriptor Account.getDescriptor()"})
  public void testAccountGetDescriptor() {
    // Arrange and Act
    Descriptor actualDescriptor = Account.getDescriptor();

    // Assert
    assertEquals("Account", actualDescriptor.getName());
    assertEquals("protocol.Account", actualDescriptor.getFullName());
    assertNull(actualDescriptor.getContainingType());
    assertFalse(actualDescriptor.isExtendable());
    assertTrue(actualDescriptor.getEnumTypes().isEmpty());
    assertTrue(actualDescriptor.getExtensions().isEmpty());
    assertTrue(actualDescriptor.getOneofs().isEmpty());
    assertTrue(actualDescriptor.getRealOneofs().isEmpty());
    assertEquals(Account.CODE_FIELD_NUMBER, actualDescriptor.getIndex());
    assertEquals(Account.LATEST_OPRATION_TIME_FIELD_NUMBER, actualDescriptor.getNestedTypes().size());
    assertEquals(ContractType.ExchangeWithdrawContract_VALUE, actualDescriptor.getFields().size());
  }

