  /**
   * Test authority {@link authority#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link authority#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"authority authority.parseDelimitedFrom(InputStream)"})
  public void testAuthorityParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{2, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    authority actualParseDelimitedFromResult = authority.parseDelimitedFrom(input);

    // Assert
    assertEquals(2, actualParseDelimitedFromResult.getUnknownFields().getSerializedSize());
    assertEquals(2, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[5];
    assertEquals(5, input.read(byteArray));
    AccountId account = actualParseDelimitedFromResult.getAccount();
    assertSame(account, account.getDefaultInstanceForType());
    authority defaultInstanceForType = actualParseDelimitedFromResult.getDefaultInstanceForType();
    assertSame(account, defaultInstanceForType.getAccount());
    assertSame(account, defaultInstanceForType.getAccountOrBuilder());
    assertSame(account, actualParseDelimitedFromResult.getAccountOrBuilder());
    assertSame(defaultInstanceForType.getDefaultInstanceForType(), defaultInstanceForType.getDefaultInstanceForType());
    assertArrayEquals("XAXAX".getBytes("UTF-8"), byteArray);
  }

