  /**
   * Test BlockHeader {@link BlockHeader#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link BlockHeader#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"BlockHeader BlockHeader.parseDelimitedFrom(InputStream)"})
  public void testBlockHeaderParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{2, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    BlockHeader actualParseDelimitedFromResult = BlockHeader.parseDelimitedFrom(input);

    // Assert
    assertEquals(2, actualParseDelimitedFromResult.getUnknownFields().getSerializedSize());
    assertEquals(2, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[5];
    assertEquals(5, input.read(byteArray));
    BlockHeader defaultInstanceForType = actualParseDelimitedFromResult.getDefaultInstanceForType();
    assertSame(defaultInstanceForType.getDefaultInstanceForType(), defaultInstanceForType.getDefaultInstanceForType());
    raw rawData = actualParseDelimitedFromResult.getRawData();
    assertSame(rawData, defaultInstanceForType.getRawData());
    assertSame(rawData, defaultInstanceForType.getRawDataOrBuilder());
    assertSame(rawData, actualParseDelimitedFromResult.getRawDataOrBuilder());
    assertSame(rawData, rawData.getDefaultInstanceForType());
    assertArrayEquals("XAXAX".getBytes("UTF-8"), byteArray);
  }

