  /**
   * Test Block {@link Block#parseDelimitedFrom(InputStream, ExtensionRegistryLite)} with {@code input}, {@code extensionRegistry}.
   * <p>
   * Method under test: {@link Block#parseDelimitedFrom(InputStream, ExtensionRegistryLite)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Block Block.parseDelimitedFrom(InputStream, ExtensionRegistryLite)"})
  public void testBlockParseDelimitedFromWithInputExtensionRegistry() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{2, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Block actualParseDelimitedFromResult = Block.parseDelimitedFrom(input, ExtensionRegistryLite.getEmptyRegistry());

    // Assert
    assertEquals(2, actualParseDelimitedFromResult.getUnknownFields().getSerializedSize());
    assertEquals(2, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[5];
    assertEquals(5, input.read(byteArray));
    BlockHeader blockHeader = actualParseDelimitedFromResult.getBlockHeader();
    Block defaultInstanceForType = actualParseDelimitedFromResult.getDefaultInstanceForType();
    assertSame(blockHeader, defaultInstanceForType.getBlockHeader());
    assertSame(blockHeader, defaultInstanceForType.getBlockHeaderOrBuilder());
    assertSame(blockHeader, actualParseDelimitedFromResult.getBlockHeaderOrBuilder());
    assertSame(blockHeader, blockHeader.getDefaultInstanceForType());
    assertSame(defaultInstanceForType.getDefaultInstanceForType(), defaultInstanceForType.getDefaultInstanceForType());
    assertArrayEquals("XAXAX".getBytes("UTF-8"), byteArray);
  }

