  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Block Block.parseFrom(ByteBuffer)"})
  public void testBlockParseFromWithByteBuffer() throws InvalidProtocolBufferException {
    // Arrange and Act
    Block actualParseFromResult = Block.parseFrom(ByteBuffer.wrap(new byte[]{}));

    // Assert
    assertEquals("", actualParseFromResult.getInitializationErrorString());
    assertEquals(0, actualParseFromResult.getSerializedSize());
    assertEquals(0, actualParseFromResult.getTransactionsCount());
    assertFalse(actualParseFromResult.hasBlockHeader());
    assertTrue(actualParseFromResult.findInitializationErrors().isEmpty());
    List<Transaction> transactionsList = actualParseFromResult.getTransactionsList();
    assertTrue(transactionsList.isEmpty());
    assertTrue(actualParseFromResult.getAllFields().isEmpty());
    assertTrue(actualParseFromResult.isInitialized());
    assertEquals(actualParseFromResult, actualParseFromResult.getDefaultInstanceForType());
    assertSame(transactionsList, actualParseFromResult.getTransactionsOrBuilderList());
  }

