  @MethodsUnderTest({"HelloMessage HelloMessage.parseFrom(byte[])"})
  public void testHelloMessageParseFromWithByte() throws InvalidProtocolBufferException {
    // Arrange and Act
    HelloMessage actualParseFromResult = HelloMessage.parseFrom(new byte[]{});

    // Assert
    assertEquals("", actualParseFromResult.getInitializationErrorString());
    assertEquals(0, actualParseFromResult.getNodeType());
    assertEquals(0, actualParseFromResult.getSerializedSize());
    assertEquals(0, actualParseFromResult.getVersion());
    assertEquals(0L, actualParseFromResult.getLowestBlockNum());
    assertEquals(0L, actualParseFromResult.getTimestamp());
    assertFalse(actualParseFromResult.hasFrom());
    assertFalse(actualParseFromResult.hasGenesisBlockId());
    assertFalse(actualParseFromResult.hasHeadBlockId());
    assertFalse(actualParseFromResult.hasSolidBlockId());
    assertTrue(actualParseFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseFromResult.getAllFields().isEmpty());
    assertTrue(actualParseFromResult.isInitialized());
    assertEquals(actualParseFromResult, actualParseFromResult.getDefaultInstanceForType());
  }

