  /**
   * Test Items {@link Items#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link Items#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Items Items.parseDelimitedFrom(InputStream)"})
  public void testItemsParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Items actualParseDelimitedFromResult = Items.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getBlockHeadersCount());
    assertEquals(0, actualParseDelimitedFromResult.getBlocksCount());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getTransactionsCount());
    assertEquals(0, actualParseDelimitedFromResult.getTypeValue());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(ItemType.ERR, actualParseDelimitedFromResult.getType());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<BlockHeader> blockHeadersList = actualParseDelimitedFromResult.getBlockHeadersList();
    assertTrue(blockHeadersList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(blockHeadersList, actualParseDelimitedFromResult.getBlockHeadersOrBuilderList());
    assertSame(blockHeadersList, actualParseDelimitedFromResult.getBlocksList());
    assertSame(blockHeadersList, actualParseDelimitedFromResult.getBlocksOrBuilderList());
    assertSame(blockHeadersList, actualParseDelimitedFromResult.getTransactionsList());
    assertSame(blockHeadersList, actualParseDelimitedFromResult.getTransactionsOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

