  public void testNodeInfo_BuilderGetDescriptor() {
    // Arrange and Act
    Descriptor actualDescriptor = NodeInfo.Builder.getDescriptor();

    // Assert
    assertEquals("NodeInfo", actualDescriptor.getName());
    assertEquals("protocol.NodeInfo", actualDescriptor.getFullName());
    assertNull(actualDescriptor.getContainingType());
    assertEquals(4, actualDescriptor.getNestedTypes().size());
    assertEquals(40, actualDescriptor.getIndex());
    assertFalse(actualDescriptor.isExtendable());
    assertTrue(actualDescriptor.getEnumTypes().isEmpty());
    assertTrue(actualDescriptor.getExtensions().isEmpty());
    assertTrue(actualDescriptor.getOneofs().isEmpty());
    assertTrue(actualDescriptor.getRealOneofs().isEmpty());
    assertEquals(Account.ALLOWANCE_FIELD_NUMBER, actualDescriptor.getFields().size());
  }

