  /**
   * Test NodeInfo_MachineInfo {@link MachineInfo#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link MachineInfo#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"MachineInfo MachineInfo.parseDelimitedFrom(InputStream)"})
  public void testNodeInfo_MachineInfoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    MachineInfo actualParseDelimitedFromResult = MachineInfo.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getJavaVersion());
    assertEquals("", actualParseDelimitedFromResult.getOsName());
    assertEquals(0, actualParseDelimitedFromResult.getCpuCount());
    assertEquals(0, actualParseDelimitedFromResult.getDeadLockThreadCount());
    assertEquals(0, actualParseDelimitedFromResult.getDeadLockThreadInfoListCount());
    assertEquals(0, actualParseDelimitedFromResult.getMemoryDescInfoListCount());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getThreadCount());
    assertEquals(0.0d, actualParseDelimitedFromResult.getCpuRate(), 0.0);
    assertEquals(0.0d, actualParseDelimitedFromResult.getProcessCpuRate(), 0.0);
    assertEquals(0L, actualParseDelimitedFromResult.getFreeMemory());
    assertEquals(0L, actualParseDelimitedFromResult.getJvmFreeMemory());
    assertEquals(0L, actualParseDelimitedFromResult.getJvmTotalMemory());
    assertEquals(0L, actualParseDelimitedFromResult.getTotalMemory());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<DeadLockThreadInfo> deadLockThreadInfoListList = actualParseDelimitedFromResult
        .getDeadLockThreadInfoListList();
    assertTrue(deadLockThreadInfoListList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(deadLockThreadInfoListList, actualParseDelimitedFromResult.getDeadLockThreadInfoListOrBuilderList());
    assertSame(deadLockThreadInfoListList, actualParseDelimitedFromResult.getMemoryDescInfoListList());
    assertSame(deadLockThreadInfoListList, actualParseDelimitedFromResult.getMemoryDescInfoListOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

