  /**
   * Test NodeInfo_PeerInfo {@link NodeInfo.PeerInfo#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link NodeInfo.PeerInfo#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"NodeInfo.PeerInfo NodeInfo.PeerInfo.parseDelimitedFrom(InputStream)"})
  public void testNodeInfo_PeerInfoParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    PeerInfo actualParseDelimitedFromResult = PeerInfo.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getHeadBlockWeBothHave());
    assertEquals("", actualParseDelimitedFromResult.getHost());
    assertEquals("", actualParseDelimitedFromResult.getLastSyncBlock());
    assertEquals("", actualParseDelimitedFromResult.getLocalDisconnectReason());
    assertEquals("", actualParseDelimitedFromResult.getNodeId());
    assertEquals("", actualParseDelimitedFromResult.getRemoteDisconnectReason());
    assertEquals(0, actualParseDelimitedFromResult.getBlockInPorcSize());
    assertEquals(0, actualParseDelimitedFromResult.getDisconnectTimes());
    assertEquals(0, actualParseDelimitedFromResult.getNodeCount());
    assertEquals(0, actualParseDelimitedFromResult.getPort());
    assertEquals(0, actualParseDelimitedFromResult.getScore());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getSyncBlockRequestedSize());
    assertEquals(0, actualParseDelimitedFromResult.getSyncToFetchSize());
    assertEquals(0.0d, actualParseDelimitedFromResult.getAvgLatency(), 0.0);
    assertEquals(0L, actualParseDelimitedFromResult.getConnectTime());
    assertEquals(0L, actualParseDelimitedFromResult.getHeadBlockTimeWeBothHave());
    assertEquals(0L, actualParseDelimitedFromResult.getInFlow());
    assertEquals(0L, actualParseDelimitedFromResult.getLastBlockUpdateTime());
    assertEquals(0L, actualParseDelimitedFromResult.getRemainNum());
    assertEquals(0L, actualParseDelimitedFromResult.getSyncToFetchSizePeekNum());
    assertEquals(0L, actualParseDelimitedFromResult.getUnFetchSynNum());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getIsActive());
    assertFalse(actualParseDelimitedFromResult.getNeedSyncFromPeer());
    assertFalse(actualParseDelimitedFromResult.getNeedSyncFromUs());
    assertFalse(actualParseDelimitedFromResult.getSyncFlag());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

