  @MethodsUnderTest({"Descriptors.Descriptor PBFTMessage.Builder.getDescriptor()"})
  public void testPBFTMessage_BuilderGetDescriptor() {
    // Arrange and Act
    Descriptor actualDescriptor = PBFTMessage.Builder.getDescriptor();

    // Assert
    assertEquals("PBFTMessage", actualDescriptor.getName());
    assertEquals("protocol.PBFTMessage", actualDescriptor.getFullName());
    assertNull(actualDescriptor.getContainingType());
    assertEquals(1, actualDescriptor.getNestedTypes().size());
    assertEquals(2, actualDescriptor.getEnumTypes().size());
    assertEquals(2, actualDescriptor.getFields().size());
    assertFalse(actualDescriptor.isExtendable());
    assertTrue(actualDescriptor.getExtensions().isEmpty());
    assertTrue(actualDescriptor.getOneofs().isEmpty());
    assertTrue(actualDescriptor.getRealOneofs().isEmpty());
    assertEquals(Account.DELEGATED_FROZEN_BALANCE_FOR_BANDWIDTH_FIELD_NUMBER, actualDescriptor.getIndex());
  }

