  /**
   * Test Permission {@link Permission#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link Permission#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Permission Permission.parseDelimitedFrom(InputStream)"})
  public void testPermissionParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Permission actualParseDelimitedFromResult = Permission.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getPermissionName());
    assertEquals(0, actualParseDelimitedFromResult.getId());
    assertEquals(0, actualParseDelimitedFromResult.getKeysCount());
    assertEquals(0, actualParseDelimitedFromResult.getParentId());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getTypeValue());
    assertEquals(0L, actualParseDelimitedFromResult.getThreshold());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(PermissionType.Owner, actualParseDelimitedFromResult.getType());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<Key> keysList = actualParseDelimitedFromResult.getKeysList();
    assertTrue(keysList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(keysList, actualParseDelimitedFromResult.getKeysOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

