  /**
   * Test Proposal {@link Proposal#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link Proposal#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Proposal Proposal.parseDelimitedFrom(InputStream)"})
  public void testProposalParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Proposal actualParseDelimitedFromResult = Proposal.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getApprovalsCount());
    assertEquals(0, actualParseDelimitedFromResult.getParametersCount());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getStateValue());
    assertEquals(0L, actualParseDelimitedFromResult.getCreateTime());
    assertEquals(0L, actualParseDelimitedFromResult.getExpirationTime());
    assertEquals(0L, actualParseDelimitedFromResult.getProposalId());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(State.PENDING, actualParseDelimitedFromResult.getState());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getApprovalsList().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getParameters().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getParametersMap().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

