  /**
   * Test ResourceReceipt {@link ResourceReceipt#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link ResourceReceipt#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"ResourceReceipt ResourceReceipt.parseDelimitedFrom(InputStream)"})
  public void testResourceReceiptParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    ResourceReceipt actualParseDelimitedFromResult = ResourceReceipt.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getResultValue());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getEnergyFee());
    assertEquals(0L, actualParseDelimitedFromResult.getEnergyPenaltyTotal());
    assertEquals(0L, actualParseDelimitedFromResult.getEnergyUsage());
    assertEquals(0L, actualParseDelimitedFromResult.getEnergyUsageTotal());
    assertEquals(0L, actualParseDelimitedFromResult.getNetFee());
    assertEquals(0L, actualParseDelimitedFromResult.getNetUsage());
    assertEquals(0L, actualParseDelimitedFromResult.getOriginEnergyUsage());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(contractResult.DEFAULT, actualParseDelimitedFromResult.getResult());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

