  /**
   * Test Transaction {@link Transaction#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link Transaction#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Transaction Transaction.parseDelimitedFrom(InputStream)"})
  public void testTransactionParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Transaction actualParseDelimitedFromResult = Transaction.parseDelimitedFrom(input);

    // Assert
    UnknownFieldSet unknownFields = actualParseDelimitedFromResult.getUnknownFields();
    assertEquals(0, unknownFields.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    Descriptor descriptorForType = actualParseDelimitedFromResult.getDescriptorForType();
    assertEquals(3, descriptorForType.getFields().size());
    assertEquals(3, descriptorForType.getNestedTypes().size());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    Transaction.raw rawData = actualParseDelimitedFromResult.getRawData();
    assertSame(unknownFields, rawData.getUnknownFields());
    assertSame(unknownFields, unknownFields.getDefaultInstanceForType());
    assertSame(rawData, actualParseDelimitedFromResult.getRawDataOrBuilder());
    assertSame(rawData, rawData.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

