  /**
   * Test Transaction_Result {@link Result#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link Result#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Result Result.parseDelimitedFrom(InputStream)"})
  public void testTransaction_ResultParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Result actualParseDelimitedFromResult = Result.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getAssetIssueID());
    assertEquals(0, actualParseDelimitedFromResult.getCancelUnfreezeV2AmountCount());
    assertEquals(0, actualParseDelimitedFromResult.getContractRetValue());
    assertEquals(0, actualParseDelimitedFromResult.getOrderDetailsCount());
    assertEquals(0, actualParseDelimitedFromResult.getRetValue());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getExchangeId());
    assertEquals(0L, actualParseDelimitedFromResult.getExchangeInjectAnotherAmount());
    assertEquals(0L, actualParseDelimitedFromResult.getExchangeReceivedAmount());
    assertEquals(0L, actualParseDelimitedFromResult.getExchangeWithdrawAnotherAmount());
    assertEquals(0L, actualParseDelimitedFromResult.getFee());
    assertEquals(0L, actualParseDelimitedFromResult.getShieldedTransactionFee());
    assertEquals(0L, actualParseDelimitedFromResult.getUnfreezeAmount());
    assertEquals(0L, actualParseDelimitedFromResult.getWithdrawAmount());
    assertEquals(0L, actualParseDelimitedFromResult.getWithdrawExpireAmount());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(code.SUCESS, actualParseDelimitedFromResult.getRet());
    assertEquals(contractResult.DEFAULT, actualParseDelimitedFromResult.getContractRet());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<MarketOrderDetail> orderDetailsList = actualParseDelimitedFromResult.getOrderDetailsList();
    assertTrue(orderDetailsList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getCancelUnfreezeV2Amount().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getCancelUnfreezeV2AmountMap().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(orderDetailsList, actualParseDelimitedFromResult.getOrderDetailsOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

