  public void testTransaction_rawParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Transaction.raw actualParseDelimitedFromResult = Transaction.raw.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getAuthsCount());
    assertEquals(0, actualParseDelimitedFromResult.getContractCount());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getExpiration());
    assertEquals(0L, actualParseDelimitedFromResult.getFeeLimit());
    assertEquals(0L, actualParseDelimitedFromResult.getRefBlockNum());
    assertEquals(0L, actualParseDelimitedFromResult.getTimestamp());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<authority> authsList = actualParseDelimitedFromResult.getAuthsList();
    assertTrue(authsList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(authsList, actualParseDelimitedFromResult.getAuthsOrBuilderList());
    assertSame(authsList, actualParseDelimitedFromResult.getContractList());
    assertSame(authsList, actualParseDelimitedFromResult.getContractOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

