  /**
   * Test Votes {@link Votes#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link Votes#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Votes Votes.parseDelimitedFrom(InputStream)"})
  public void testVotesParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Votes actualParseDelimitedFromResult = Votes.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getNewVotesCount());
    assertEquals(0, actualParseDelimitedFromResult.getOldVotesCount());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<Vote> newVotesList = actualParseDelimitedFromResult.getNewVotesList();
    assertTrue(newVotesList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(newVotesList, actualParseDelimitedFromResult.getNewVotesOrBuilderList());
    assertSame(newVotesList, actualParseDelimitedFromResult.getOldVotesList());
    assertSame(newVotesList, actualParseDelimitedFromResult.getOldVotesOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

