  /**
   * Test Witness {@link Witness#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link Witness#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Witness Witness.parseDelimitedFrom(InputStream)"})
  public void testWitnessParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    Witness actualParseDelimitedFromResult = Witness.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals("", actualParseDelimitedFromResult.getUrl());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getLatestBlockNum());
    assertEquals(0L, actualParseDelimitedFromResult.getLatestSlotNum());
    assertEquals(0L, actualParseDelimitedFromResult.getTotalMissed());
    assertEquals(0L, actualParseDelimitedFromResult.getTotalProduced());
    assertEquals(0L, actualParseDelimitedFromResult.getVoteCount());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertFalse(actualParseDelimitedFromResult.getIsJobs());
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

