  /**
   * Test Witness_Builder {@link Witness.Builder#getDescriptor()}.
   * <p>
   * Method under test: {@link Witness.Builder#getDescriptor()}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Descriptors.Descriptor Witness.Builder.getDescriptor()"})
  public void testWitness_BuilderGetDescriptor() {
    // Arrange and Act
    Descriptor actualDescriptor = Witness.Builder.getDescriptor();

    // Assert
    assertEquals("Witness", actualDescriptor.getName());
    assertEquals("protocol.Witness", actualDescriptor.getFullName());
    assertNull(actualDescriptor.getContainingType());
    assertFalse(actualDescriptor.isExtendable());
    assertTrue(actualDescriptor.getEnumTypes().isEmpty());
    assertTrue(actualDescriptor.getExtensions().isEmpty());
    assertTrue(actualDescriptor.getNestedTypes().isEmpty());
    assertTrue(actualDescriptor.getOneofs().isEmpty());
    assertTrue(actualDescriptor.getRealOneofs().isEmpty());
    assertEquals(Account.CREATE_TIME_FIELD_NUMBER, actualDescriptor.getFields().size());
    assertEquals(Account.LATEST_ASSET_OPERATION_TIME_FIELD_NUMBER, actualDescriptor.getIndex());
  }
